import React from 'react';
import { Search, Bell, Calendar, Menu, X, ChevronLeft } from 'lucide-react';

const TopBar = ({ mobileMenuOpen, setMobileMenuOpen, location, notifications, toggleSidebar, isMobile }) => {
  const getPageTitle = () => {
    const path = location.pathname;
    const titles = {
      '/dashboard': 'Tableau de bord',
      '/dashboard/users': 'Utilisateurs',
      '/dashboard/products': 'Produits',
      '/dashboard/orders': 'Commandes',
      '/dashboard/analytics': 'Analytique',
      '/dashboard/messages': 'Messages',
      '/dashboard/settings': 'Paramètres',
    };
    return titles[path] || 'Tableau de bord';
  };

  return (
    <header className="sticky top-0 z-40 bg-white/95 dark:bg-neutral-900/95 backdrop-blur-xl border-b border-neutral-200/50 dark:border-neutral-800/50">
      <div className="flex items-center justify-between px-4 md:px-6 py-3 md:py-4">
        <div className="flex items-center space-x-2 md:space-x-4">
          {!isMobile && (
            <button
              onClick={toggleSidebar}
              className="hidden lg:flex p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800"
            >
              <ChevronLeft className="h-5 w-5" />
            </button>
          )}

          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="lg:hidden p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800"
          >
            {mobileMenuOpen ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
          </button>

          <h2 className="text-lg md:text-xl font-bold text-neutral-900 dark:text-white truncate max-w-[200px] md:max-w-none">
            {getPageTitle()}
          </h2>
        </div>

        <div className="flex items-center space-x-2 md:space-x-4">
          {/* Search - Mobile avec icône seulement */}
          <div className="relative">
            <button className="lg:hidden p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800">
              <Search className="h-5 w-5" />
            </button>

            <div className="hidden md:block">
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-4 w-4 md:h-5 md:w-5 text-neutral-400" />
                </div>
                <input
                  type="search"
                  placeholder="Rechercher..."
                  className="pl-10 pr-4 py-2 w-40 md:w-56 lg:w-64 rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 transition-all text-sm md:text-base"
                />
              </div>
            </div>
          </div>

          {/* Notifications */}
          <div className="relative">
            <button className="relative p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800">
              <Bell className="h-5 w-5" />
              {notifications.filter(n => n.unread).length > 0 && (
                <span className="absolute -top-1 -right-1 h-2 w-2 md:h-3 md:w-3 bg-red-500 rounded-full border border-white dark:border-neutral-900"></span>
              )}
            </button>
          </div>

          {/* Calendar - Desktop seulement */}
          <button className="hidden md:flex items-center space-x-2 px-3 md:px-4 py-2 rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white/50 dark:bg-neutral-800/50 text-neutral-700 dark:text-neutral-300 hover:border-primary-500 hover:text-primary-600 dark:hover:text-primary-400 transition-colors">
            <Calendar className="h-4 w-4 md:h-5 md:w-5" />
            <span className="text-sm md:text-base">Jan 15</span>
          </button>
        </div>
      </div>
    </header>
  );
};

export default TopBar;
